    parts := []string{"reports", "2026", "summary.txt"}
    fmt.Println(filepath.Join(parts...))
    fmt.Println(filepath.Join("/base", "/tmp"))
    fmt.Println(filepath.Join("reports", "draft", "..", "final.txt"))
